import type { Request, Response } from 'express'
import { prisma } from '@/config/prisma'
import { ApiError } from '@/middleware/errorHandler'
import { created, noContent, ok } from '@/utils/apiResponse'
import * as service from './reports.service'

function requireUser(req: Request) {
  if (!req.user) throw new ApiError(401, 'Authentication required')
  return req.user
}

async function loadCurrentUser(req: Request) {
  const authUser = requireUser(req)
  // req.user only carries id/role/departmentId (the JWT payload) — the
  // service needs the display name too (for "generated by" text baked into
  // the file itself), so it's fetched once per request here rather than
  // widening the access-token payload for a cosmetic field.
  const dbUser = await prisma.user.findUnique({ where: { id: authUser.id }, select: { name: true } })
  return { id: authUser.id, role: authUser.role, departmentId: authUser.departmentId, name: dbUser?.name ?? 'Unknown' }
}

export async function generate(req: Request, res: Response) {
  const user = await loadCurrentUser(req)
  const data = await service.generate(req.body, user)
  return created(res, data)
}

export async function list(req: Request, res: Response) {
  const user = await loadCurrentUser(req)
  const data = await service.list(user)
  return ok(res, data)
}

export async function download(req: Request, res: Response) {
  const user = await loadCurrentUser(req)
  const { content, filename, contentType } = await service.getFile(req.params.id as string, user)
  res.setHeader('Content-Type', contentType)
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`)
  return res.send(content)
}

export async function remove(req: Request, res: Response) {
  const user = await loadCurrentUser(req)
  await service.remove(req.params.id as string, user)
  return noContent(res)
}
